INSERT INTO funnel_versions(version, configuration) VALUES ('trail-variants-v1', '{"id":"trail-variants-v1","name":"Trail planning","start":"welcome","steps":[{"id":"welcome","type":"information","title":"Plan a fictional weekend trail","body":"Answer a few questions to discover a sample trail plan. This is a demonstration, not a booking service.","next":"pace"},{"id":"pace","type":"single-select","title":"Choose your pace","options":[{"id":"gentle","label":"Gentle stroll"},{"id":"active","label":"Active hike"}],"next":"interests"},{"id":"interests","type":"multi-select","title":"What would you like to see?","body":"Choose one or two interests.","options":[{"id":"forest","label":"Forest"},{"id":"water","label":"Waterfalls"},{"id":"view","label":"Mountain views"}],"min":1,"max":2,"next":"hours"},{"id":"hours","type":"number","title":"How many hours do you have?","body":"Enter a number from 1 to 8.","min":1,"max":8,"next":"prepare"},{"id":"prepare","type":"information","title":"Before you head out","body":"Bring water, check the weather, and tell someone your route. These are fictional suggestions.","next":"result"},{"id":"result","type":"result","title":"Your sample trail plan is ready","body":"A nearby woodland loop is a good starting point for your fictional weekend.","cta":{"label":"Explore trail ideas","href":"https://www.nps.gov/subjects/trails/index.htm"}}],"variants":{"B":{"steps":{"welcome":{"title":"Build your weekend trail plan","body":"Start with your available time, then choose the trail you would enjoy. This is a fictional demonstration.","next":"hours"},"hours":{"next":"pace"},"pace":{"next":"interests"},"interests":{"next":"prepare"},"result":{"title":"Your next trail starts here","body":"Explore a fictional trail plan shaped around your available time and interests.","cta":{"label":"Find your next trail","href":"https://www.nps.gov/subjects/trails/index.htm"}}}}}}');
